def recall_at_k(ranked, relevant, k):
    rel = set(relevant)
    if not rel:
        return None
    return len(set(ranked[:k]) & rel) / len(rel)


def mrr(rankings, relevants):
    rr = []
    for ranked, relevant in zip(rankings, relevants):
        if not relevant:
            continue
        r = next((i + 1 for i, d in enumerate(ranked) if d in relevant), None)
        rr.append(1 / r if r else 0.0)
    return sum(rr) / len(rr)

