import math
import json
import numpy as np
from llm_apps_ops_l1 import fit_tfidf, embed

NOTES = json.load(open('llm-apps-notes.json'))
TEXTS = [n['text'] for n in NOTES['notes']]
QUERIES = [(q['text'], q['relevant']) for q in NOTES['queries']]
_M = fit_tfidf(TEXTS)
_U, _s, _Vt = np.linalg.svd(_M['X'], full_matrices=False)


def tfidf_search(text):
    s = _M['X'] @ embed(text, _M)
    return sorted(range(len(s)), key=lambda i: (-s[i], i))


def lsa_search(text, k=8):
    V = _Vt[:k].T
    D = _M['X'] @ V
    q = embed(text, _M) @ V
    s = D @ q / (np.linalg.norm(D, axis=1) * np.linalg.norm(q))
    return sorted(range(len(s)), key=lambda i: (-s[i], i))


